/* eslint-disable space-in-parens */

import zeros = require( '@stdlib/ndarray/zeros' );
import scalar2ndarray = require( '@stdlib/ndarray/from-scalar' );
import Complex128 = require( '@stdlib/complex/float64/ctor' );
import axpb = require( './index' );


// TESTS //

// The function returns an ndarray...
{
	const x = zeros( [ 2, 2 ], {
		'dtype': 'float64'
	});

	axpb( x, 5.0, 3.0 ); // $ExpectType float64ndarray
	axpb( x, 5.0, 3.0, {} ); // $ExpectType float64ndarray
}

// The function returns an ndarray (complex scalars)...
{
	const x = zeros( [ 2, 2 ], {
		'dtype': 'complex128'
	});
	const alpha = new Complex128( 2.0, 0.0 );
	const beta = new Complex128( 1.0, 0.0 );

	axpb( x, alpha, beta ); // $ExpectType complex128ndarray
	axpb( x, alpha, beta, {} ); // $ExpectType complex128ndarray
}

// The function returns an ndarray (ndarray alpha and beta)...
{
	const x = zeros( [ 2, 2 ], {
		'dtype': 'float64'
	});
	const alpha = scalar2ndarray( 5.0, {
		'dtype': 'float64'
	});
	const beta = scalar2ndarray( 3.0, {
		'dtype': 'float64'
	});

	axpb( x, alpha, beta ); // $ExpectType float64ndarray
	axpb( x, alpha, beta, {} ); // $ExpectType float64ndarray
}

// The compiler throws an error if the function is provided a first argument which is not an ndarray...
{
	axpb( '5', 5.0, 3.0 ); // $ExpectError
	axpb( 5, 5.0, 3.0 ); // $ExpectError
	axpb( true, 5.0, 3.0 ); // $ExpectError
	axpb( false, 5.0, 3.0 ); // $ExpectError
	axpb( null, 5.0, 3.0 ); // $ExpectError
	axpb( void 0, 5.0, 3.0 ); // $ExpectError
	axpb( {}, 5.0, 3.0 ); // $ExpectError
	axpb( ( x: number ): number => x, 5.0, 3.0 ); // $ExpectError

	axpb( '5', 5.0, 3.0, {} ); // $ExpectError
	axpb( 5, 5.0, 3.0, {} ); // $ExpectError
	axpb( true, 5.0, 3.0, {} ); // $ExpectError
	axpb( false, 5.0, 3.0, {} ); // $ExpectError
	axpb( null, 5.0, 3.0, {} ); // $ExpectError
	axpb( void 0, 5.0, 3.0, {} ); // $ExpectError
	axpb( {}, 5.0, 3.0, {} ); // $ExpectError
	axpb( ( x: number ): number => x, 5.0, 3.0, {} ); // $ExpectError
}

// The compiler throws an error if the function is provided a second argument which is not a number, complex-like, or ndarray...
{
	const x = zeros( [ 2, 2 ], {
		'dtype': 'float64'
	});

	axpb( x, '5', 3.0 ); // $ExpectError
	axpb( x, true, 3.0 ); // $ExpectError
	axpb( x, false, 3.0 ); // $ExpectError
	axpb( x, null, 3.0 ); // $ExpectError
	axpb( x, [], 3.0 ); // $ExpectError
	axpb( x, {}, 3.0 ); // $ExpectError
	axpb( x, ( x: number ): number => x, 3.0 ); // $ExpectError

	axpb( x, '5', 3.0, {} ); // $ExpectError
	axpb( x, true, 3.0, {} ); // $ExpectError
	axpb( x, false, 3.0, {} ); // $ExpectError
	axpb( x, null, 3.0, {} ); // $ExpectError
	axpb( x, [], 3.0, {} ); // $ExpectError
	axpb( x, {}, 3.0, {} ); // $ExpectError
	axpb( x, ( x: number ): number => x, 3.0, {} ); // $ExpectError
}

// The compiler throws an error if the function is provided a third argument which is not a number, complex-like, or ndarray...
{
	const x = zeros( [ 2, 2 ], {
		'dtype': 'float64'
	});

	axpb( x, 5.0, '3' ); // $ExpectError
	axpb( x, 5.0, true ); // $ExpectError
	axpb( x, 5.0, false ); // $ExpectError
	axpb( x, 5.0, null ); // $ExpectError
	axpb( x, 5.0, [] ); // $ExpectError
	axpb( x, 5.0, ( x: number ): number => x ); // $ExpectError

	axpb( x, 5.0, '3', {} ); // $ExpectError
	axpb( x, 5.0, true, {} ); // $ExpectError
	axpb( x, 5.0, false, {} ); // $ExpectError
	axpb( x, 5.0, null, {} ); // $ExpectError
	axpb( x, 5.0, [], {} ); // $ExpectError
	axpb( x, 5.0, ( x: number ): number => x, {} ); // $ExpectError
}

// The compiler throws an error if the function is provided a fourth argument which is not an object...
{
	const x = zeros( [ 2, 2 ], {
		'dtype': 'float64'
	});

	axpb( x, 5.0, 3.0, '5' ); // $ExpectError
	axpb( x, 5.0, 3.0, 5 ); // $ExpectError
	axpb( x, 5.0, 3.0, true ); // $ExpectError
	axpb( x, 5.0, 3.0, false ); // $ExpectError
	axpb( x, 5.0, 3.0, null ); // $ExpectError
	axpb( x, 5.0, 3.0, [] ); // $ExpectError
	axpb( x, 5.0, 3.0, ( x: number ): number => x ); // $ExpectError
}

// The compiler throws an error if the function is provided an invalid `dims` option...
{
	const x = zeros( [ 2, 2 ], {
		'dtype': 'float64'
	});

	axpb( x, 5.0, 3.0, { 'dims': '5' } ); // $ExpectError
	axpb( x, 5.0, 3.0, { 'dims': 5 } ); // $ExpectError
	axpb( x, 5.0, 3.0, { 'dims': true } ); // $ExpectError
	axpb( x, 5.0, 3.0, { 'dims': false } ); // $ExpectError
	axpb( x, 5.0, 3.0, { 'dims': null } ); // $ExpectError
	axpb( x, 5.0, 3.0, { 'dims': {} } ); // $ExpectError
	axpb( x, 5.0, 3.0, { 'dims': ( x: number ): number => x } ); // $ExpectError
}

// The compiler throws an error if the function is provided an unsupported number of arguments...
{
	const x = zeros( [ 2, 2 ], {
		'dtype': 'float64'
	});

	axpb(); // $ExpectError
	axpb( x ); // $ExpectError
	axpb( x, 5.0 ); // $ExpectError
	axpb( x, 5.0, 3.0, {}, {} ); // $ExpectError
}
